package dnsresolver

import (
	"strings"
	"testing"
)

func TestStripHostsBlock(t *testing.T) {
	initial := `127.0.0.1 localhost
::1 ip6-localhost

# ========================================================
# Auto-generated by Ex3-UI DNS Resolver (Geo-unblock)
# Do not edit manually - managed automatically
104.21.65.111 chatgpt.com
104.21.65.111 api.openai.com
# ========================================================

192.168.1.1 router
`
	cleaned := stripHostsBlock(initial)
	if strings.Contains(cleaned, "chatgpt.com") {
		t.Errorf("expected chatgpt.com to be removed, got:\n%s", cleaned)
	}
	if !strings.Contains(cleaned, "127.0.0.1 localhost") {
		t.Errorf("expected localhost to be preserved, got:\n%s", cleaned)
	}
	if !strings.Contains(cleaned, "192.168.1.1 router") {
		t.Errorf("expected router to be preserved, got:\n%s", cleaned)
	}
}

// A stray marker mention, or a block whose footer was lost, must never cost the
// operator the rest of /etc/hosts.
func TestStripHostsBlockLeavesIncompleteBlocksAlone(t *testing.T) {
	stray := "127.0.0.1 localhost\n# Auto-generated by Ex3-UI SmartDNS (Geo-unblock) is documented in the wiki\n192.168.1.1 router\n"
	if got := stripHostsBlock(stray); got != stray {
		t.Fatalf("a stray marker mention changed the file:\n%s", got)
	}

	broken := "127.0.0.1 localhost\n\n# ========================================================\n" +
		"# Auto-generated by Ex3-UI SmartDNS (Geo-unblock)\n" +
		"# Do not edit manually - managed automatically\n" +
		"1.2.3.4 chatgpt.com\n192.168.1.1 router\n"
	if got := stripHostsBlock(broken); got != broken {
		t.Fatalf("an unterminated block truncated the file:\n%s", got)
	}

	clean := "127.0.0.1 localhost\n"
	if got := stripHostsBlock(clean); got != clean {
		t.Fatalf("a file without a block changed:\n%s", got)
	}
}

func TestBuildDnsQuery(t *testing.T) {
	msg := buildDnsQuery("chatgpt.com")
	if len(msg.Questions) != 1 {
		t.Fatalf("expected 1 question, got %d", len(msg.Questions))
	}
	if msg.Questions[0].Name.String() != "chatgpt.com." {
		t.Errorf("expected chatgpt.com., got %s", msg.Questions[0].Name.String())
	}
}

func TestSettingsDefaults(t *testing.T) {
	st := GetSettings()
	if st.DnsServer == "" {
		t.Error("expected non-empty default DNS server")
	}
	if st.IntervalHours <= 0 {
		t.Errorf("expected positive interval, got %d", st.IntervalHours)
	}
	if len(st.Domains) == 0 {
		t.Error("expected default domain list")
	}
}
